def decide(trace):
    # OpenCores I2C command encoding: I2C_CMD_WRITE = 4'b0100.
    WRITE = 0b0100
    matches = []

    for edge, row in enumerate(trace):
        inputs = row.get("inputs", {})
        outputs = row.get("outputs", {})

        if (
            inputs.get("cmd") == WRITE
            and inputs.get("din") == 1
            and inputs.get("ena") == 1
            and inputs.get("nReset") == 1
            and inputs.get("rst") == 0
            and inputs.get("scl_i") == 1
            and inputs.get("sda_i") == 0
        ):
            matches.append((edge, outputs.get("sda_oen")))

    if not matches:
        return (None, None, "The specified WRITE/arbitration scenario never occurred.")

    for edge, sda_oen in matches:
        if sda_oen != 1:
            return (
                False,
                edge,
                "For WRITE with din=1, SDA must be released; active-low sda_oen must be 1, including during arbitration checking.",
            )

    return (
        True,
        matches[0][0],
        "For WRITE with din=1, the controller releases SDA, so sda_oen must be 1.",
    )
